	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/threads/{threadId}/messages", wrapper.SendMessage)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/threads/{threadId}/reset", wrapper.ResetThread)
